/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_devolucao_livro` AFTER UPDATE ON `emprestimos` FOR EACH ROW BEGIN
    -- O sistema verifica se o status mudou para 'Devolvido' agora
    IF NEW.status = 'Devolvido' AND OLD.status != 'Devolvido' THEN
        UPDATE livros
        SET quantidade_disponivel = quantidade_disponivel + 1
        WHERE id = NEW.livro_id;
    END IF;
END */;;
DELIMITER ;
